#!/usr/bin/env ruby
# frozen_string_literal: true
#
# register-fonts.rb — wire merged custom fonts into an Xcode project so SwiftUI
# `.font(.custom(...))` actually renders instead of silently falling back to system.
#
# Locofy-generated code ships font files (Fonts/*.ttf|otf) plus a UIAppFonts
# declaration in its OWN Info.plist. After merge into an existing Xcode project
# the font registration is routinely lost:
#   - if the target uses a physical Info.plist, the merged UIAppFonts array is
#     usually missing from it;
#   - if the target uses GENERATE_INFOPLIST_FILE = YES (synthesized plist) there
#     is no plist to carry UIAppFonts at all, so fonts are never registered.
# Either way the .ttf renders as system font in the simulator.
#
# This script is gem-free (no `xcodeproj` — that gem cannot open Xcode 16
# PBXFileSystemSynchronizedRootGroup projects), idempotent, and ADAPTIVE:
#   - physical Info.plist (INFOPLIST_FILE set)  -> merge UIAppFonts via PlistBuddy
#   - synthesized plist (GENERATE_INFOPLIST_FILE = YES) -> inject runtime
#     CTFontManager registration into the @main App struct.
#
# Bundle membership: modern Xcode 16 projects use synchronized folder groups
# (PBXFileSystemSynchronizedRootGroup) that auto-include fonts as resources, so no
# Copy Bundle Resources surgery is needed. Runtime registration also reads from
# the built bundle, so it is robust regardless of how the .ttf got bundled. For
# classic (non-synchronized) projects where the fonts are not referenced at all,
# the script prints a WARN — those need a manual target-membership add in Xcode.
#
# Usage:  ruby register-fonts.rb [PROJECT_ROOT]   (defaults to CWD)

require 'set'

# Force UTF-8. A non-interactive shell (the agent runs this without an interactive
# locale) often defaults Encoding.default_external to US-ASCII, which makes File.read
# raise `invalid byte sequence in US-ASCII` on any Swift/pbxproj file containing a
# non-ASCII byte (curly quotes, em dashes, arrows or emoji in comments). All external
# reads below also `.scrub` as a second line of defense against genuinely malformed bytes.
Encoding.default_external = Encoding::UTF_8
Encoding.default_internal = Encoding::UTF_8

def read_text(path)
  File.read(path, encoding: 'UTF-8').scrub
end

proj_root = File.expand_path(ARGV[0] || Dir.pwd)
EXCLUDE = %r{/(\.locofy|DerivedData|build|\.build|Pods|node_modules|__MACOSX)/}.freeze

def sh(*args)
  out = IO.popen(args, err: %i[child out], &:read)
  [out, $?.exitstatus]
end

xcodeproj_path = Dir.glob(File.join(proj_root, '**', '*.xcodeproj'))
                    .reject { |p| p =~ EXCLUDE }
                    .min_by(&:length)
abort("FONT_FIX: FAIL — no .xcodeproj under #{proj_root}") unless xcodeproj_path

pbx_path = File.join(xcodeproj_path, 'project.pbxproj')
pbx = read_text(pbx_path)
srcroot = File.dirname(xcodeproj_path)

font_files = Dir.glob(File.join(proj_root, '**', '*.{ttf,otf,TTF,OTF}'))
                .reject { |p| p =~ EXCLUDE }
                .map { |p| File.expand_path(p) }
                .uniq
if font_files.empty?
  puts 'FONT_FIX: no .ttf/.otf font files in project — nothing to register.'
  puts 'FONT_FIX: RESULT=OK mode=none'
  exit 0
end
font_basenames = font_files.map { |f| File.basename(f) }.uniq.sort

# ---- bundle-membership sanity (synchronized folders auto-include fonts) -----
synchronized = pbx.include?('PBXFileSystemSynchronizedRootGroup')
unless synchronized
  referenced = font_basenames.all? { |b| pbx.include?(b) }
  unless referenced
    warn 'FONT_FIX: WARN — classic (non-synchronized) project and fonts are not ' \
         'referenced in project.pbxproj. They may not be in Copy Bundle Resources; ' \
         'add the Fonts folder to the app target in Xcode if the fonts do not render.'
  end
end

# ---- detect Info.plist mode from build settings ----------------------------
infoplist_file = pbx[/\bINFOPLIST_FILE\s*=\s*"?([^";\n]+)"?\s*;/, 1]
infoplist_file = nil if infoplist_file && infoplist_file.strip.empty?
generate_yes   = pbx =~ /\bGENERATE_INFOPLIST_FILE\s*=\s*YES\s*;/

if infoplist_file
  # ---- physical Info.plist -> merge UIAppFonts via PlistBuddy ---------------
  resolved = infoplist_file.gsub('$(SRCROOT)', srcroot).gsub('$(PROJECT_DIR)', srcroot)
  plist_abs = File.absolute_path(resolved, srcroot)
  abort("FONT_FIX: FAIL — INFOPLIST_FILE=#{infoplist_file} -> missing #{plist_abs}") unless File.exist?(plist_abs)

  pb = '/usr/libexec/PlistBuddy'
  existing, _ = sh(pb, '-c', 'Print :UIAppFonts', plist_abs)
  if existing.include?('Does Not Exist')
    sh(pb, '-c', 'Add :UIAppFonts array', plist_abs)
    existing = ''
  end
  added = []
  font_basenames.each do |name|
    next if existing.include?(name)
    _o, st = sh(pb, '-c', "Add :UIAppFonts: string #{name}", plist_abs)
    added << name if st.zero?
  end
  puts "FONT_FIX: UIAppFonts +#{added.length} in #{File.basename(plist_abs)}#{added.empty? ? ' (already present)' : ": #{added.join(', ')}"} [mode=physical]"
  puts 'FONT_FIX: RESULT=OK mode=physical'
  exit 0
end

unless generate_yes
  warn 'FONT_FIX: WARN — no INFOPLIST_FILE and GENERATE_INFOPLIST_FILE != YES; defaulting to runtime registration.'
end

# ---- synthesized plist -> runtime CTFontManager registration ---------------
app_swift = Dir.glob(File.join(proj_root, '**', '*.swift'))
                .reject { |p| p =~ EXCLUDE }
                .find { |p| read_text(p) =~ /@main\b/ }
abort('FONT_FIX: FAIL — synthesized plist but no @main App struct found') unless app_swift

src = read_text(app_swift)
if src.include?('LocofyFontRegistration')
  puts "FONT_FIX: runtime registration already present in #{File.basename(app_swift)} [mode=synthesized]"
  puts 'FONT_FIX: RESULT=OK mode=synthesized'
  exit 0
end

# ensure CoreText import
unless src =~ /^\s*import\s+CoreText\b/
  src = if src =~ /^\s*import\s+SwiftUI\b.*\n/
          src.sub(/^(\s*import\s+SwiftUI\b.*\n)/, "\\1import CoreText\n")
        else
          "import CoreText\n#{src}"
        end
end

# Wire the registration call. The enhanced App struct frequently already has an
# `init()` (e.g. splash setup) — adding a SECOND init() is a Swift compile error
# (invalid redeclaration). So: if an init() already exists after @main, inject the
# call as its first statement; otherwise add a fresh init(). Scope the search to the
# text after `@main` so a helper struct's init() elsewhere in the file is not touched.
main_idx = src.index(/@main\b/)
abort("FONT_FIX: FAIL — no @main found in #{File.basename(app_swift)}") unless main_idx
head = src[0...main_idx]
tail = src[main_idx..-1]

multiline_init = /\n([ \t]*)init\s*\([^)]*\)\s*(?:async\s+|throws\s+)*\{[ \t]*\n/
if tail =~ multiline_init
  indent = Regexp.last_match(1)
  tail = tail.sub(multiline_init) { |m| "#{m}#{indent}    LocofyFontRegistration.registerAll()\n" }
  src = head + tail
elsif tail =~ /\binit\s*\(/
  abort("FONT_FIX: FAIL — App already has a single-line init() in #{File.basename(app_swift)}; " \
        'add `LocofyFontRegistration.registerAll()` as its first statement manually.')
else
  app_struct = /(@main\s*\n\s*(?:public\s+|final\s+)?struct\s+\w+\s*:\s*App\s*\{[ \t]*\n)/
  abort("FONT_FIX: FAIL — @main App struct not matched in #{File.basename(app_swift)}") unless src =~ app_struct
  src = src.sub(app_struct, "\\1    init() { LocofyFontRegistration.registerAll() }\n\n")
end

src = "#{src.rstrip}\n" + <<~SWIFT

  // Locofy: registers bundled custom fonts at launch. The app target uses a
  // synthesized Info.plist, so UIAppFonts cannot carry them. Idempotent.
  enum LocofyFontRegistration {
      static func registerAll() {
          for ext in ["ttf", "otf"] {
              for url in Bundle.main.urls(forResourcesWithExtension: ext, subdirectory: nil) ?? [] {
                  CTFontManagerRegisterFontsForURL(url as CFURL, .process, nil)
              }
          }
      }
  }
SWIFT

File.write(app_swift, src)
puts "FONT_FIX: runtime registration injected into #{File.basename(app_swift)} (#{font_basenames.length} fonts) [mode=synthesized]"
puts 'FONT_FIX: RESULT=OK mode=synthesized'
